#include <stdio.h>
#include <string.h>
#define MOD 1000000007

int W, H, K;
long long dp[2][21];
long long f[21][21]; // f[pos][new_pos] = number of valid patterns moving pos to new_pos

int main() {
    scanf("%d %d %d", &W, &H, &K);

    // Enumerate valid patterns
    memset(f, 0, sizeof(f));
    int total = 1 << (W-1);
    for (int mask = 0; mask < total; mask++) {
        // Check valid: no two consecutive bits
        if (mask & (mask >> 1)) continue;
        // For each position, determine where it goes
        for (int pos = 1; pos <= W; pos++) {
            int new_pos = pos;
            if (pos <= W-1 && (mask >> (pos-1)) & 1) new_pos = pos + 1;
            else if (pos >= 2 && (mask >> (pos-2)) & 1) new_pos = pos - 1;
            f[pos][new_pos] = (f[pos][new_pos] + 1) % MOD;
        }
    }

    int cur = 0;
    memset(dp[cur], 0, sizeof(dp[cur]));
    dp[cur][1] = 1;

    for (int h = 0; h < H; h++) {
        int nxt = 1 - cur;
        memset(dp[nxt], 0, sizeof(dp[nxt]));
        for (int pos = 1; pos <= W; pos++) {
            if (!dp[cur][pos]) continue;
            for (int np = 1; np <= W; np++) {
                dp[nxt][np] = (dp[nxt][np] + dp[cur][pos] * f[pos][np]) % MOD;
            }
        }
        cur = nxt;
    }

    printf("%lld\n", dp[cur][K]);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MOD 1000000007

int main() {
    int W, H, K;
    scanf("%d %d %d", &W, &H, &K);

    // dp[j] = ways to be at vertical line j at current height
    long long dp[1001] = {0};
    dp[1] = 1; // start from leftmost vertical line at the top

    for (int h = 1; h <= H; h++) {
        long long new_dp[1001] = {0};

        // For each possible combination of horizontal lines at this height
        // We use bitmask to represent which adjacent pairs have a horizontal line
        // Only possible masks: no two adjacent bits set (no shared endpoints)

        // Iterate all masks from 0 to (1 << (W-1)) - 1
        int maxMask = 1 << (W - 1);
        for (int mask = 0; mask < maxMask; mask++) {
            int valid = 1;
            for (int b = 0; b < W - 2; b++) {
                if ((mask & (1 << b)) && (mask & (1 << (b+1)))) {
                    valid = 0;
                    break;
                }
            }
            if (!valid) continue;

            // For each vertical line, simulate movement
            long long temp[1001];
            memcpy(temp, dp, sizeof(temp));

            // Apply horizontal swaps according to mask
            for (int b = 0; b < W - 1; b++) {
                if (mask & (1 << b)) {
                    // swap temp[b+1] and temp[b+2] (lines are 1-indexed)
                    long long t = temp[b+1];
                    temp[b+1] = temp[b+2];
                    temp[b+2] = t;
                }
            }

            // After applying swaps, everyone moves straight down
            for (int j = 1; j <= W; j++) {
                new_dp[j] = (new_dp[j] + temp[j]) % MOD;
            }
        }

        memcpy(dp, new_dp, sizeof(dp));
    }

    printf("%lld\n", dp[K] % MOD);

    return 0;
}

#include <stdio.h>
#include <string.h>

#define MOD 1000000007LL

int main(void) {
    int H, W, K;
    if (scanf("%d %d %d", &H, &W, &K) != 3) return 0;

    /*
      For each row, we can place horizontal bars between adjacent columns.
      Let bit i (0-based) represent a bar between vertical lines i and i+1.
      Valid row patterns have no adjacent 1s.
    */

    long long dp[105][10];
    memset(dp, 0, sizeof(dp));
    dp[0][0] = 1;  // start at the leftmost line (0-based)

    int maxMask = 1 << (W - 1);

    for (int r = 0; r < H; r++) {
        for (int mask = 0; mask < maxMask; mask++) {
            // invalid if adjacent bars exist
            if (mask & (mask << 1)) continue;

            for (int col = 0; col < W; col++) {
                int to = col;
                if (col > 0 && (mask & (1 << (col - 1)))) {
                    to = col - 1;          // connected to left
                } else if (col < W - 1 && (mask & (1 << col))) {
                    to = col + 1;          // connected to right
                }
                dp[r + 1][to] = (dp[r + 1][to] + dp[r][col]) % MOD;
            }
        }
    }

    printf("%lld\n", dp[H][K - 1] % MOD);
    return 0;
}

