public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt(), W = sc.nextInt(), K = sc.nextInt();

        // Enumerate all valid row patterns
        List<int[]> patterns = new ArrayList<>();
        for (int mask = 0; mask < (1 << (W - 1)); mask++) {
            boolean valid = true;
            for (int i = 0; i < W - 2; i++) {
                if (((mask >> i) & 1) == 1 && ((mask >> (i + 1)) & 1) == 1) {
                    valid = false; break;
                }
            }
            if (valid) {
                int[] move = new int[W + 1];
                for (int p = 1; p <= W; p++) {
                    if (p <= W - 1 && ((mask >> (p - 1)) & 1) == 1) move[p] = p + 1;
                    else if (p >= 2 && ((mask >> (p - 2)) & 1) == 1) move[p] = p - 1;
                    else move[p] = p;
                }
                patterns.add(move);
            }
        }

        long[] dp = new long[W + 1];
        dp[1] = 1;

        for (int h = 0; h < H; h++) {
            long[] ndp = new long[W + 1];
            for (int[] pat : patterns) {
                for (int p = 1; p <= W; p++) {
                    ndp[pat[p]] = (ndp[pat[p]] + dp[p]) % MOD;
                }
            }
            dp = ndp;
        }

        System.out.println(dp[K]);
    }
}

import java.util.Scanner;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int W = sc.nextInt();
        int H = sc.nextInt();
        int K = sc.nextInt();
        sc.close();

        if (K < 1 || K > W) {
            System.out.println(0);
            return;
        }

        long[][] mat = new long[W][W];
        for (int i = 0; i < W; i++) {
            mat[i][i] = 1; // stay
            if (i > 0) mat[i][i - 1] = 1; // swap left
            if (i < W - 1) mat[i][i + 1] = 1; // swap right
        }

        long[][] result = matrixPow(mat, H);

        System.out.println(result[0][K - 1]);
    }

    static long[][] matrixMul(long[][] a, long[][] b) {
        int n = a.length;
        long[][] res = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (a[i][k] == 0) continue;
                for (int j = 0; j < n; j++) {
                    res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % MOD;
                }
            }
        }
        return res;
    }

    static long[][] matrixPow(long[][] mat, int exp) {
        int n = mat.length;
        long[][] res = new long[n][n];
        for (int i = 0; i < n; i++) res[i][i] = 1;
        long[][] base = mat;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = matrixMul(res, base);
            }
            base = matrixMul(base, base);
            exp >>= 1;
        }
        return res;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();
        int K = fs.nextInt();

        // dp[i][j]: number of ways after i rows, being at vertical line j (0-indexed)
        long[][] dp = new long[H + 1][W];
        dp[0][0] = 1;

        // Enumerate all valid horizontal bar patterns for one row.
        // A pattern is a bitmask of length W-1:
        // bit b = 1 means there is a horizontal bar between line b and b+1.
        List<Integer> patterns = new ArrayList<>();
        int limit = 1 << Math.max(0, W - 1);
        for (int mask = 0; mask < limit; mask++) {
            if ((mask & (mask << 1)) == 0) { // no adjacent bars
                patterns.add(mask);
            }
        }

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                long cur = dp[i][j];
                if (cur == 0) continue;

                for (int mask : patterns) {
                    int nj = j;
                    if (j > 0 && ((mask >> (j - 1)) & 1) == 1) {
                        nj = j - 1; // move left
                    } else if (j < W - 1 && ((mask >> j) & 1) == 1) {
                        nj = j + 1; // move right
                    }
                    dp[i + 1][nj] += cur;
                    if (dp[i + 1][nj] >= MOD) dp[i + 1][nj] -= MOD;
                }
            }
        }

        System.out.println(dp[H][K - 1] % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
const int MOD = 1e9 + 7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W, H, K;
    cin >> W >> H >> K;

    vector<long long> dp(W + 2, 0);
    dp[1] = 1;

    for (int h = 0; h < H; h++) {
        vector<long long> ndp(W + 2, 0);
        // Try all subsets of possible horizontal lines at this height
        // They can't be adjacent, so we can iterate over bitmasks of length W-1
        int M = W - 1;
        for (int mask = 0; mask < (1 << M); mask++) {
            bool ok = true;
            for (int i = 0; i < M - 1; i++) {
                if ((mask & (1 << i)) && (mask & (1 << (i + 1)))) {
                    ok = false;
                    break;
                }
            }
            if (!ok) continue;

            // Apply transitions for this mask
            for (int pos = 1; pos <= W; pos++) {
                if (dp[pos] == 0) continue;
                int newpos = pos;
                // Check if there's a horizontal line from pos-1 to pos
                if (pos > 1 && (mask & (1 << (pos - 2)))) {
                    newpos = pos - 1;
                }
                // Check if there's a horizontal line from pos to pos+1
                else if (pos < W && (mask & (1 << (pos - 1)))) {
                    newpos = pos + 1;
                }
                // else stays same
                ndp[newpos] = (ndp[newpos] + dp[pos]) % MOD;
            }
        }
        dp = ndp;
    }

    cout << dp[K] % MOD << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, K;
    cin >> H >> W >> K;
    --K; // 0-indexed target column

    // All possible horizontal-bar patterns for one row:
    // bit i means a bar between vertical lines i and i+1.
    // Valid iff no adjacent bits are both 1.
    vector<int> patterns;
    for (int mask = 0; mask < (1 << (W - 1)); ++mask) {
        if (mask & (mask << 1)) continue; // adjacent bars not allowed
        patterns.push_back(mask);
    }

    vector<long long> dp(W, 0), ndp(W, 0);
    dp[0] = 1; // start at the leftmost vertical line

    for (int r = 0; r < H; ++r) {
        fill(ndp.begin(), ndp.end(), 0);

        for (int mask : patterns) {
            for (int j = 0; j < W; ++j) {
                int nj = j;
                if (j > 0 && (mask & (1 << (j - 1)))) {
                    // bar between j-1 and j, move left
                    nj = j - 1;
                } else if (j < W - 1 && (mask & (1 << j))) {
                    // bar between j and j+1, move right
                    nj = j + 1;
                }
                ndp[nj] = (ndp[nj] + dp[j]) % MOD;
            }
        }

        dp.swap(ndp);
    }

    cout << dp[K] % MOD << '\n';
    return 0;
}
